sys_ui_action.script:
function onSubmit() {
    // 检查当前记录是否已被拒绝
    if (g_form.getValue('my_request_status') != 'rejected') {
        alert('只有被拒绝的请求才能重新提交');
        return false;
    }

    // 创建Ajax请求
    var ga = new GlideAjax('ResubmitHandler');
    ga.addParam('sysparm_name', 'processResubmit');
    ga.addParam('sysparm_sysid', g_form.getUniqueValue());

    // 显示加载指示器
    g_form.showFieldMsg('my_request_status', '正在处理重新提交...', 'info');

    // 禁用提交按钮防止重复提交
    var btn = g_form.getControl('submit_button');
    if (btn) btn.disabled = true;

    // 设置回调函数
    ga.getXMLAnswer(function(response) {
        if (response === 'success') {
            // 成功后刷新页面
            g_form.addInfoMessage('请求已成功重新提交并进入审批流程');

            // 添加较长延迟确保工作流完全处理
            setTimeout(function() {
                window.location.reload(true);
            }, 3000); // 3秒后刷新
        } else {
            // 显示错误信息
            g_form.addErrorMessage('操作失败: ' + response);
            g_form.showFieldMsg('my_request_status', '操作失败: ' + response, 'error');

            // 重新启用提交按钮
            var btn = g_form.getControl('submit_button');
            if (btn) btn.disabled = false;
        }
    });

    // 阻止表单自动提交
    return false;
}
